<script lang="ts">
 import {onMount} from 'svelte';
 import {budgetRead,visiblePoll} from '$lib/request-budget';
 import marketStudy from '$lib/research/first-market-study.json';
 let {mode}:{mode:'paper'|'live'}=$props();
 let autoLive=$state(false);let data:any=$state(null),paper:any=$state(null),markets:any=$state(null),failure=$state(''),marketError=$state(''),operator=$state(false),signed=$state(false),loading=$state(false),working=$state(''),controlMessage=$state('');
 const money=(v:any)=>typeof v==='number'&&Number.isFinite(v)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v):'—';
 const stamp=(v:any)=>v?new Date(v).toLocaleString('en-GB',{timeZone:'Africa/Lagos'})+' WAT':'No record';
 const accounts=()=>Object.entries(paper?.paper??{}).map(([key,value]:[string,any])=>({key,bee:key.split(':')[0],...value}));
 const total=(field:string)=>accounts().reduce((s,a)=>s+(a[field]??0),0);
 const stale=()=>!paper?.lastCycle?.lastBar||Date.now()-paper.lastCycle.lastBar>900000||paper.lastCycle.status!=='evaluated';
 async function get(view:string){return budgetRead('/api/workspaces?view='+view);}
 async function refresh(){if(loading)return;loading=true;try{if(mode==='paper'){paper=await get('paper');data=paper;}else if(signed)data=await get('live');else throw Error('Sign in to retrieve your private live account.');failure='';}catch(e){failure=e instanceof Error?e.message:String(e);}finally{loading=false;}}
 async function quotes(){if(!operator||mode!=='live')return;try{markets=await get('markets');marketError='';}catch(e){marketError=e instanceof Error?e.message:String(e);}}
 async function loadAccount(){try{const session=await budgetRead('/api/auth/session');signed=!!session.user;operator=session.user?.role==='admin';if(mode==='live')await refresh();}catch(e){failure=e instanceof Error?e.message:String(e);}}
 async function act(action:string){working=action;controlMessage='';try{const r=await fetch('/api/workspaces',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});const d=await r.json();if(!r.ok)throw Error(d.message??d.error??'Action failed');controlMessage='Paper control recorded. Review refreshed evidence below.';await refresh();}catch(e){controlMessage=e instanceof Error?e.message:String(e);}finally{working='';}}
 onMount(()=>{if(mode==='paper')void refresh();const stop=visiblePoll(async()=>{if(mode==='live'&&(!autoLive||!signed))return true;await refresh();return !failure;},mode==='paper'?300000:60000);return stop;});
 function line(history:any[]){if(!history?.length)return '';const values=history.map(r=>r.equity),min=Math.min(...values),span=Math.max(1,Math.max(...values)-min);return history.map((r,i)=>`${i*300/Math.max(1,history.length-1)},${100-(r.equity-min)/span*80}`).join(' ');}
</script>
<svelte:head><title>{mode==='live'?'Live':'Paper'} Workspace · OmieBot Trading</title><meta name="robots" content="noindex"/></svelte:head>
<main><header><a class="brand" href="/">⬡ Omie<span>Bot</span></a><nav aria-label="Trading navigation"><a class:chosen={mode==='live'} href="/live">Live Workspace</a><a class:chosen={mode==='paper'} href="/paper">Paper Workspace</a><a href="/research">Research Lab</a><a href="/login">{signed?'Account':'Sign in'}</a></nav></header>
 <div class="heading"><p>Public evidence refreshes every five minutes while visible and online. Private feeds load only on request.</p>{#if mode==='live'}<button onclick={()=>void loadAccount()}>Load my live account</button><label><input type="checkbox" bind:checked={autoLive}/> Refresh my loaded account every 60 seconds</label>{:else}<button onclick={()=>void loadAccount()}>Load operator controls</button>{/if}</div>
 <div class="heading"><div><span class="eyebrow">{mode==='live'?'OKX LIVE ACCOUNT · REAL FUNDS ONLY':'REAL MARKET OBSERVATIONS · SIMULATED CAPITAL'}</span><h1>{mode==='live'?'Live':'Paper'} Workspace<span>.</span></h1><p>{mode==='live'?'Broker balances and actual broker orders belong here. Paper equity is never counted as invested money.':'A shared research fleet with an autonomous five-minute market cycle. Recorded decisions, simulated fills and actual model fitting on retained market bars.'}</p></div><button disabled={loading} onclick={()=>{void refresh();void quotes();}}>{loading?'Refreshing…':'Refresh evidence ↻'}</button></div>
 {#if failure}<aside role="alert">{failure}. Previously loaded evidence may be stale.</aside>{/if}
 {#if mode==='live'}<section class="live-state"><span class="eyebrow">{data?.status??'AWAITING ACCOUNT EVIDENCE'}</span><h2>{data?.executionEnabled?'Live execution enabled':'Live execution is not active'}</h2><p>{data?.reason??'Sign in to inspect verified account readiness. No account balance is assumed.'}</p><div class="metrics"><article><small>AVAILABLE LIVE USDT</small><strong>{typeof data?.balance?.cash==='number'?data.balance.cash.toFixed(2)+' USDT':'—'}</strong></article><article><small>LIVE ACCOUNT EQUITY · USD</small><strong>{money(data?.balance?.equity)}</strong></article><article><small>ACTUAL BROKER ORDERS</small><strong>{data?.orders?.length??'—'}</strong></article></div><small>Account evidence: {stamp(data?.at)} · Private to the account operator. Customer allocations require their own verified account mapping.</small></section>{:else}<div class="statusbar"><span class:bad={stale()}>{paper?.paused?'PAUSED':stale()?'FEED UNAVAILABLE / STALE · ABSTAIN':'FRESH CLOSED BARS · PAPER EVALUATION'}</span><span>{paper?.symbol??'BTC/USD'} · Alpaca US · five-minute bars</span></div><div class="metrics"><article><small>SHARED PAPER-FLEET EQUITY</small><strong>{paper?money(total('equity')):'—'}</strong><p>{accounts().length} recorded paper accounts</p></article><article><small>NET SIMULATED P&L</small><strong>{paper?money(total('pnl')):'—'}</strong><p>Includes simulation fees and slippage</p></article><article><small>RETAINED MARKET BARS</small><strong>{paper?.dataset?.bars??'—'}</strong><p>One instrument and venue; kept separate from OKX</p></article><article><small>LAST MARKET EVALUATION</small><strong class="time">{stamp(paper?.lastCycle?.at)}</strong><p>{paper?.lastCycle?.status??'No completed cycle'} · refresh every five minutes</p></article></div>
 {#if paper?.lastCycle?.reason}<aside>{paper.lastCycle.reason}</aside>{/if}
 <div class="bees">{#each accounts() as a}<article class="bee"><span class="eyebrow">{a.bee} BEE · PAPER</span><h2>{money(a.equity)}</h2><p class:loss={a.pnl<0}>{money(a.pnl)} net simulated P&L</p><span class="position">{a.quantity>0?'LONG':'FLAT'} · {paper?.symbol}</span><svg viewBox="0 0 300 120" role="img" aria-label={`${a.bee} recorded paper equity`}><path d="M0 100H300M0 60H300M0 20H300" stroke="#ffffff0c"/><polyline points={line(a.history??[])} fill="none" stroke="#f4c647" stroke-width="2"/></svg><h3>{a.lastDecision?.action?.toUpperCase()??'NO CALL'}</h3><p>{a.lastDecision?.reason}</p><small>{stamp(a.lastDecision?.at)}</small><dl><div><dt>Simulated fills</dt><dd>{a.trades??0}</dd></div><div><dt>Accumulated fees</dt><dd>{money(a.fees??0)}</dd></div><div><dt>Learned shadow probability</dt><dd>{typeof a.lastDecision?.shadowProbability==='number'?a.lastDecision.shadowProbability.toFixed(3):'Awaiting fitted model'}</dd></div><div><dt>Forward shadow observations</dt><dd>{a.forwardShadow?.samples??0}</dd></div></dl><p class="fine">Learned predictions are scored forward when the next bar arrives. They cannot authorize orders. Baseline rules continue independently.</p></article>{:else}<section class="empty"><h2>No shared paper-fleet accounts recorded yet</h2><p>The operator can start the isolated Alpaca paper cycle. No historical trades or results will be invented.</p></section>{/each}</div>
 {#if operator}<section class="controls"><div><h2>Paper operations</h2><p>Controls affect only the isolated simulated workspace. Live funds are excluded.</p></div><div>{#each [['start','Start / resume + collect'],['cycle','Evaluate fresh bar'],['pause','Pause paper']] as control}<button disabled={!!working} onclick={()=>act(control[0])}>{working===control[0]?'Working…':control[1]}</button>{/each}</div>{#if controlMessage}<p role="status">{controlMessage}</p>{/if}</section>{/if}
 {/if}
 <section class="market-panel"><div class="section-heading"><h2>Market watch</h2><span>ACTUAL BID / ASK · 60 SECOND SHARED CACHE</span></div><p>Supported scope: BTC, ETH, SOL, LTC and DOGE against USD on Alpaca US. These are provider quotes, not order fills. Other markets require their own verified adapters and entitlements.</p>{#if mode==='live'}<p>These are research-feed prices. They are not executable OKX quotes; OKX venue data must be independently verified before orders.</p>{/if}{#if marketError}<aside>{marketError}</aside>{:else if !signed}<a href="/login">Sign in to inspect account-authorized market data →</a>{/if}{#if markets}<div class="table"><table><thead><tr><th>Instrument</th><th>Midpoint</th><th>Bid</th><th>Ask</th><th>Spread (bps)</th><th>Observed</th></tr></thead><tbody>{#each markets.quotes as q}<tr><td>{q.symbol}</td><td>{money(q.price)}</td><td>{money(q.bid)}</td><td>{money(q.ask)}</td><td>{q.spreadBps.toFixed(2)}</td><td>{stamp(q.time)} {Date.now()-q.time>120000?'STALE':''}</td></tr>{/each}</tbody></table></div>{/if}</section>
 <section><div class="section-heading"><h2>Actual training evidence</h2><a href="https://github.com/Omaledanjumaogale/beebots/actions/workflows/omiebot-training.yml" target="_blank" rel="noreferrer">External training workflow</a><span>RETAINED MARKET DATA · DAILY 04:00 WAT</span></div><p>These reports fit numerical logistic weights. They do not fine-tune Laya. Development screening, forward paper observation and live approval remain different stages.</p><div class="training">{#each paper?.training?.results??[] as report}<article><span class="eyebrow">{report.bee}</span><h3>{report.result.status}</h3><p>{report.result.samples??0} retained bars · {report.result.epochs??0} fitting epochs</p><dl><div><dt>Development Brier score</dt><dd>{report.result.metrics?.brier?.toFixed(4)??'—'}</dd></div><div><dt>Training-prevalence baseline</dt><dd>{report.result.baseline?.brier?.toFixed(4)??'—'}</dd></div><div><dt>Costed long-entry proxy</dt><dd>{report.result.metrics?.trades??'—'} entries</dd></div></dl><small>{stamp(report.result.at)}</small><p>{report.result.reason??'Awaiting dataset and completed training.'}</p><code>{report.result.datasetSha256?.slice(0,24)??'No dataset hash'}{report.result.datasetSha256?'…':''}</code><strong class="approval">Execution approval: no</strong></article>{/each}</div></section>
 <section class="market-panel"><div class="section-heading"><h2>First actual-market tournament</h2><span>HISTORICAL RESEARCH · NOT LIVE ROI</span></div><p>{marketStudy.manifest.bars} actual BTC/USD bars · five fixed candidates · purged 60/20/20 chronological partitions. Validation selected {marketStudy.selected_candidate}; the untouched final segment then lost money at every cost stress. This candidate is not approved.</p><div class="table"><table><thead><tr><th>Round-trip cost</th><th>Final return proxy</th><th>Buy-and-hold proxy</th><th>Entries</th><th>Abstention</th></tr></thead><tbody>{#each marketStudy.final_holdout??[] as result}<tr><td>{result.round_trip_cost_bps} bps</td><td class="loss">{(result.net_return_proxy*100).toFixed(2)}%</td><td>{(result.buy_hold_return_proxy*100).toFixed(2)}%</td><td>{result.entries}</td><td>{(result.abstention_fraction*100).toFixed(1)}%</td></tr>{/each}</tbody></table></div><p class="fine">Run {stamp(marketStudy.manifest.created_at_utc)}. These simplified research baselines differ from production position/stop logic. Next-open entry and horizon-close exit proxies omit depth, intrabar losses and latency. The inspected holdout is consumed; it cannot be reused as fresh release evidence.</p><code>CSV SHA256: {marketStudy.manifest.dataset_sha256.slice(0,24)}…</code></section>
 {#if mode==='paper'}<section><h2>Recorded simulated fills</h2><div class="table"><table><thead><tr><th>Bee</th><th>Side</th><th>Price</th><th>Notional</th><th>Fee</th><th>Time</th></tr></thead><tbody>{#each accounts().flatMap(a=>(a.fills??[]).map((f:any)=>({...f,bee:a.bee}))).sort((a,b)=>b.at-a.at) as fill}<tr><td>{fill.bee}</td><td>{fill.side}</td><td>{money(fill.price)}</td><td>{money(fill.notional)}</td><td>{money(fill.fee)}</td><td>{stamp(fill.at)}</td></tr>{:else}<tr><td colspan="6">No simulated fills. Qualified conditions are required; training does not force trades.</td></tr>{/each}</tbody></table></div></section>{:else}<section><h2>Actual live broker orders</h2><div class="table"><table><thead><tr><th>Symbol</th><th>Side</th><th>Status</th><th>Filled quantity</th><th>Average fill</th></tr></thead><tbody>{#each data?.orders??[] as order}<tr><td>{order.symbol}</td><td>{order.side}</td><td>{order.status}</td><td>{order.filledQty}</td><td>{order.filledPrice??'—'}</td></tr>{:else}<tr><td colspan="5">No verified live order records. Paper fills are excluded.</td></tr>{/each}</tbody></table></div></section>{/if}
 {#if mode==='live'}<section class="live-state"><h2>Your OKX connection</h2><p>Link your own live trading account with a minimum 100 USDT allocation. API credentials are verified, encrypted on the server, and isolated by your authenticated profile.</p><a href="/connect/okx">Connect / update OKX account →</a>{#if data?.policy}<p>Allocation {data.policy.allocation} USDT · order cap {data.policy.maxOrder} USDT · exposure cap {data.policy.maxExposure} USDT · daily loss pause {data.policy.maxDailyLoss} USDT · four entries per day · spot only.</p>{/if}</section>{/if}
 <footer>OmieBot Trading · Paper and live ledgers stay separate. Training completion is not proof of profitability. Missing evidence is never converted into a balance or a trade.</footer>
</main>
<style>
 main{max-width:1500px;margin:auto;padding:28px 5%;color:#f0f0df}header,nav,.heading,.section-heading,.statusbar{display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{font-size:25px;font-weight:800}.brand span,h1 span{color:#f4c647}header{padding-bottom:24px;border-bottom:1px solid #3a3b29}nav{font-size:12px;flex-wrap:wrap}a{color:#bfc4ab}.chosen{color:#f4c647;border-bottom:1px solid;padding-bottom:5px}.heading{margin:45px 0 30px;align-items:flex-start}.heading p{max-width:720px}.eyebrow,small{font-size:9px;letter-spacing:1px;color:#c2b67c}.eyebrow{text-transform:uppercase;color:#f4c647}h1{font-size:clamp(32px,5vw,60px);letter-spacing:-2px;margin:15px 0}p{font-size:12px;line-height:1.8;color:#a3ae92}button{border:1px solid #76663a;padding:12px 15px;border-radius:5px;color:#f4c647;font-size:11px}button:disabled{opacity:.5}.statusbar{padding:15px;border:1px solid #525d35;font-size:10px;color:#b9ce8e;background:#9dac3310}.bad{color:#e2ad79}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:20px 0}.metrics article,.bee,.training article,.controls,.live-state,.market-panel{padding:22px;border:1px solid #3e442c;background:#13180f;border-radius:9px;min-width:0}.metrics strong{display:block;font-size:29px;margin:15px 0}.metrics .time{font-size:15px;line-height:1.6}.metrics p{font-size:10px}.bees,.training{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.bee{border-top:2px solid #c5a445}.bee h2{font-size:33px;margin:18px 0 0}.bee h3{color:#f4c647}.bee svg{display:block;width:100%;height:160px;margin:25px 0}.position{font-size:10px;color:#c9d69c}.loss{color:#e7a296}.fine{font-size:10px}dl{font-size:10px;margin:20px 0}dl>div{display:flex;justify-content:space-between;gap:14px;border-bottom:1px solid #333d25;padding:10px 0}dt{color:#a7b191}dd{margin:0;text-align:right}section{margin-top:35px}h2{font-size:21px}.section-heading>span{font-size:8px;color:#b7aa79}.table{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:11px;text-align:left}td,th{padding:15px 12px;border-bottom:1px solid #353f26}th{color:#b7aa79;font-size:9px}.controls>div:last-of-type{display:flex;flex-wrap:wrap;gap:10px}.training code{font-size:9px;color:#bfc9a7;word-break:break-all}.approval{display:block;font-size:10px;color:#e2b267;margin-top:18px}.training p{font-size:11px}aside{padding:15px;border:1px solid #8d6947;background:#dca24c0a;font-size:12px;color:#e2bc8f;line-height:1.8;margin:15px 0}.live-state .metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.live-state{border-color:#7a6336}.empty{padding:25px}.empty h2{font-size:19px}footer{margin:45px 0 10px;padding-top:20px;border-top:1px solid #39412c;font-size:10px;color:#99a683;line-height:1.8}@media(max-width:1000px){.metrics{grid-template-columns:1fr 1fr}.bees,.training{grid-template-columns:1fr}.heading{gap:20px}header{align-items:flex-start}.live-state .metrics{grid-template-columns:1fr 1fr}.section-heading{align-items:flex-start;flex-direction:column;gap:10px}}@media(max-width:600px){main{padding:20px}header{flex-direction:column;gap:20px}nav{gap:15px;font-size:10px}.heading{flex-direction:column;margin-top:30px}.heading button{align-self:flex-start}.metrics{gap:10px}.metrics article{padding:15px}.metrics strong{font-size:24px}.metrics small{font-size:8px}.statusbar{align-items:flex-start;flex-direction:column;gap:10px}.live-state .metrics{grid-template-columns:1fr}.live-state{padding:18px}.section-heading h2{font-size:20px}.metrics .time{font-size:12px}dd{max-width:55%}}
</style>
